class Solution {
  public boolean hasIncreasingSubarrays(List<Integer> nums, int k) {
    int n = nums.size();
    int[] run = new int[n]; // length of strictly increasing run ending at i
    for (int i = 0; i < n; i++) {
      run[i] = i > 0 && nums.get(i) > nums.get(i - 1) ? run[i - 1] + 1 : 1;
    }
    for (int end = k - 1; end + k < n; end++) {
      if (run[end] >= k && run[end + k] >= k) return true;
    }
    return false;
  }
}
